// === Tab: mySketch ===
let canvas
let leafShader
let leaves
let branches

function setup() {
	canvas = createCanvas(1112, 834, WEBGL)
	pixelDensity(1)
	leafShader = createShader(vert, frag)
	reset()
}

function reset() {
	leaves = []
	branches = []

	const addBranch = (from, prevAngle, prevScale, depth) => {
		let angle = prevAngle
		if (depth === 0) {
			angle = prevAngle + random(-1,1)*PI*0.01
		} else {
			while (abs(angle - prevAngle) < PI*0.05) {
				angle = prevAngle + random(-1,1)*PI*map(depth, 0, 5, 0.3, 0.1, true)
			}
		}
		const scale = prevScale * random(0.9, 1.2)
		const offset = p5.Vector.fromAngle(angle, scale * 120)
		const to = from.copy().add(offset)
		branches.push({ from, to })
		let numChildren
		if (depth === 4) {
			numChildren = 0
		} else if (leaves.length > 10) {
			numChildren = 0
		} else if (depth <= 3) {
			numChildren = random([2, 3, 3])
		} else {
			numChildren = random([0, 0, 1, 1, 2, 3])
		}
		if (numChildren === 0) {
			addLeaf(to.x, to.y)
		} else {
			for (let i = 0; i < numChildren; i++) {
				addBranch(to.copy(), angle, scale, depth+1)
			}
		}
	}

	const addLeaf = (x, y) => {
		var scale = random(25, 100)
		const verts = [0,1,2].map((i) => createVector(
			scale * cos(TWO_PI*i/3 + randomGaussian(0, 0.4)),
			scale * sin(TWO_PI*i/3 + randomGaussian(0, 0.4))
		))
		leaves.push({ x, y, verts })
	}

	addBranch(
		createVector(-width*0.1, height*0.6),
		//createVector(),
		-PI*0.4,
		1,
		0
	)
	const avg = { x: 0, y: 0 }
	for (const { x, y } of leaves) {
		avg.x += x
		avg.y += y
	}
	avg.x /= leaves.length
	avg.y /= leaves.length
	for (const leaf of leaves) {
		leaf.x -= avg.x
	}
	for (const { from, to } of branches) {
		from.x -= avg.x
		to.x -= avg.x
	}
}

function wind(time, x, y, leaf) {
	const s = leaf ? 1.1 : 0.7
	return [
		20*(sin(time + x*0.004 + y*0.003)+s*0.5*sin(time*3.5+x*0.002+y*0.005+100)),
		15*(sin(time + x*0.0035 + y*0.004+50)+s*0.5*sin(time*3.8+x*0.004 +y*0.002+200)),
	]
}

let lastIdx = 0
function draw() {
	background(255)
	const time = millis()/1000
	const idx = floor(time/5)
	if (lastIdx !== idx) {
		lastIdx = idx
		reset()
	}

	drawingContext.disable(drawingContext.DEPTH_TEST)

	push()
	noFill()
	stroke('#4a4842')
	strokeWeight(4)
	for (const { from, to } of branches) {
		const [fromOffX, fromOffY] = wind(time, from.x, from.y)
		const [toOffX, toOffY] = wind(time, to.x, to.y)
		line(
			from.x + fromOffX,
			from.y + fromOffY,
			to.x + toOffX,
			to.y + toOffY,
		)
	}
	pop()

	push()
	noStroke()
	for (const { x, y, verts } of leaves) {
		push()
		const [xOff, yOff] = wind(time, x, y, true)
		translate(x+xOff, y+yOff)
		shader(leafShader)
		leafShader.setUniform('pixelSize', [width*pixelDensity(), height*pixelDensity()])
		leafShader.setUniform('backContent', canvas)
		beginShape(TRIANGLES)
		for (const { x, y } of verts) {
			vertex(x, y)
		}
		endShape()
		pop()
	}
	pop()
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: leafShader ===
const vert = `
precision mediump float;
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec2 vTexCoord;
varying vec3 vNormal;
varying vec3 vPosition;
varying vec3 vObjPosition;

void main(void) {
  vec4 objSpacePosition = vec4(aPosition, 1.0);

  vObjPosition = objSpacePosition.xyz;
  vec4 worldSpacePosition = uModelViewMatrix * objSpacePosition;
  gl_Position = uProjectionMatrix * worldSpacePosition;
  vTexCoord = aTexCoord;
  vPosition = worldSpacePosition.xyz;
  vNormal = uNormalMatrix * aNormal;
}
`

const frag = `
precision mediump float;
varying vec2 vTexCoord;
varying vec3 vNormal;
varying vec3 vPosition;
varying vec3 vObjPosition;
uniform mat3 uNormalMatrix;
uniform sampler2D backContent;
uniform vec2 pixelSize;

const float PI = ${Math.PI.toFixed(10)};

float map(float val, float inA, float inB, float outA, float outB) {
  return (val - inA) / (inB - inA) * (outB - outA) + outA;
}

// Noise functions
// https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
float rand(float n) {
	return fract(sin(n) * 43758.5453123);
}
float rand(vec2 n) { 
	return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}
float noise(float p) {
	float fl = floor(p);
	float fc = fract(p);
	return mix(rand(fl), rand(fl + 1.0), fc);
}
float noise(vec2 n) {
	const vec2 d = vec2(0.0, 1.0);
	vec2 b = floor(n);
	vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
	return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
}

const int NUM_SAMPLES = 9;

void main() {
	vec2 origCoord = gl_FragCoord.xy / pixelSize;
	origCoord.y = 1. - origCoord.y;

	vec2 pixelCoord = gl_FragCoord.xy;

	vec3 color = vec3(0.,0.,0.);

	for (int i = 0; i < NUM_SAMPLES; i++) {
		float sampleOffset = float(i) * 123.456789;
		vec2 noiseOffset = vec2(
			fract(10. * noise(pixelCoord * 0.2) + sampleOffset) - 0.5,
			fract(10. * noise(pixelCoord * 0.2 + 10. + sampleOffset)) - 0.5
		) * 0.06;
		/*float frac = float(i)/float(NUM_SAMPLES);
		float angle = ${Math.PI*13} * frac +
			123.456 * fract(noise(pixelCoord.x * 0.1238 + pixelCoord.y*0.05123));
		vec2 noiseOffset = vec2(
			cos(angle),
			sin(angle)
		) * frac * 0.15 * 0.75;*/
		float sample = texture2D(backContent, origCoord + noiseOffset).x;
		vec3 sampleColor = mix(
			vec3(0., 97., 68.)/255.,
			vec3(211., 255., 89.)/255.,
			pow(sample*0.9, 2.)
		);
		color += sampleColor;
	}
	color /= float(NUM_SAMPLES);
	//color = mix(texture2D(backContent, origCoord).xyz, vec3(0.,0.,0.), 0.2);

	gl_FragColor = vec4(color, 1.0);
}
`

